import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Persistent entity types from store layer (main domain structs in store/*.go root, not Find/Update/Delete variants)
ENTITY_TYPES = [
    "Attachment", "Memo", "MemoRelation", "MemoShare", "User", "UserSetting",
    "UserIdentity", "IdentityProvider", "Inbox", "InstanceSetting", "Reaction",
    "RowStatus",  # maybe not entity
    "AuthenticationConfigState",  # check if entity
]

def get_go_package_dir(filepath):
    """Return package path like server/router/api/v1"""
    rel = os.path.relpath(filepath, REPO)
    return os.path.dirname(rel)

def is_outside_store(pkg_dir):
    return not (pkg_dir == "store" or pkg_dir.startswith("store/"))

# Collect all .go files outside store
files_outside = []
for root, dirs, files in os.walk(REPO):
    if "/.git" in root or "/proto/gen" in root:
        continue
    rel_root = os.path.relpath(root, REPO)
    if rel_root == "store" or rel_root.startswith("store" + os.sep):
        continue
    for f in files:
        if f.endswith(".go"):
            files_outside.append(os.path.join(root, f))

# For each entity, count packages that reference store.TypeName
entity_pkg_refs = {e: set() for e in ENTITY_TYPES}

patterns = {e: re.compile(r'\bstore\.' + re.escape(e) + r'\b') for e in ENTITY_TYPES}

for filepath in files_outside:
    pkg = get_go_package_dir(filepath)
    try:
        with open(filepath, 'r', errors='ignore') as fh:
            content = fh.read()
    except:
        continue
    # Only count if file imports store at all
    if "github.com/usememos/memos/store" not in content and "store." not in content:
        continue
    for entity, pat in patterns.items():
        if pat.search(content):
            entity_pkg_refs[entity].add(pkg)

# Sort by count
ranked = sorted(((e, len(pkgs), sorted(pkgs)) for e, pkgs in entity_pkg_refs.items()), key=lambda x: -x[1])

print("Rankings (packages outside store referencing store.<Type>):")
for e, count, pkgs in ranked:
    if count > 0:
        print(f"  {e}: {count} packages")
        for p in pkgs[:8]:
            print(f"    - {p}")
        if len(pkgs) > 8:
            print(f"    ... and {len(pkgs)-8} more")
PYEOF

perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @entities = qw(Attachment Memo MemoRelation MemoShare User UserSetting UserIdentity IdentityProvider Inbox InstanceSetting Reaction RowStatus AuthenticationConfigState);
my %refs; $refs{$_} = {} for @entities;

sub pkg_dir {
  my ($f) = @_;
  (my $rel = $f) =~ s/^\Q$REPO\E\///;
  $rel =~ s/\/[^\/]+$//;
  return $rel;
}

sub outside_store {
  my ($d) = @_;
  return 0 if $d eq "store" || index($d, "store/") == 0;
  return 1;
}

open my $find, "-|", "find", $REPO, "-name", "*.go", "-not", "-path", "*/.git/*", "-not", "-path", "*/proto/gen/*" or die $!;
while (<$find>) {
  chomp;
  my $f = $_;
  my $pkg = pkg_dir($f);
  next unless outside_store($pkg);
  open my $fh, "<", $f or next;
  local $/; my $c = <$fh>; close $fh;
  next unless $c =~ /store\./ || $c =~ /usememos\/memos\/store/;
  for my $e (@entities) {
    next unless $c =~ /\bstore\.$e\b/;
    $refs{$e}{$pkg} = 1;
  }
}
close $find;

my @ranked = sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @entities;
print "Rankings:\n";
for my $e (@ranked) {
  my @pkgs = sort keys %{$refs{$e}};
  next unless @pkgs;
  print "$e: ", scalar(@pkgs), " packages\n";
  for my $p (@pkgs[0..7]) { print "  - $p\n"; }
  print "  ... and ", scalar(@pkgs)-8, " more\n" if @pkgs > 8;
}
'

