use strict; use warnings;
my $REPO = "/bench/repo";
# Main persistent entity structs from store/*.go (excluding Find/Update/Delete/Query/Config/Mutation variants)
my @entities = qw(
  Attachment Memo MemoRelation MemoShare User UserSetting UserIdentity
  IdentityProvider Inbox InstanceSetting Reaction
);
my %refs; $refs{$_} = {} for @entities;

sub pkg_dir {
  my ($f) = @_;
  (my $rel = $f) =~ s/^\Q$REPO\E\///;
  $rel =~ s/\/[^\/]+$//;
  return $rel;
}
sub outside_data_layer {
  my ($d) = @_;
  return 0 if $d eq "store" || index($d, "store/") == 0;
  return 1;
}

open my $find, "-|", "find", $REPO, "-name", "*.go", "-not", "-path", "*/.git/*" or die $!;
while (<$find>) {
  chomp; my $f = $_; my $pkg = pkg_dir($f);
  next unless outside_data_layer($pkg);
  open my $fh, "<", $f or next; local $/; my $c = <$fh>; close $fh;
  for my $e (@entities) {
    next unless $c =~ /\bstore\.$e\b/;
    $refs{$e}{$pkg} = 1;
  }
}
close $find;

for my $e (sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @entities) {
  my @pkgs = sort keys %{$refs{$e}};
  print "$e: ", scalar(@pkgs), "\n" if @pkgs;
  for my $p (@pkgs) { print "  $p\n"; }
  print "\n";
}
'

