args.command:
perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my %entity_patterns = (
  User => [qr/\bstore\.User\b/, qr/\bstore\.FindUser\b/, qr/\bstore\.UpdateUser\b/, qr/\bstore\.DeleteUser\b/],
  Memo => [qr/\bstore\.Memo\b/, qr/\bstore\.FindMemo\b/, qr/\bstore\.UpdateMemo\b/, qr/\bstore\.DeleteMemo\b/],
  Attachment => [qr/\bstore\.Attachment\b/, qr/\bstore\.FindAttachment\b/, qr/\bstore\.UpdateAttachment\b/, qr/\bstore\.DeleteAttachment\b/],
);
my %refs;
sub pkg_dir { my ($f)=@_; (my $r=$f)=~s/^\Q$REPO\E\///; $r=~s/\/[^\/]+$//; $r }
sub outside { my ($d)=@_; return 0 if $d eq "store" || index($d,"store/")==0; 1 }
open F, "-|", "find", $REPO, "-name", "*.go", "-not", "-path", "*/.git/*";
while(<F>){ chomp; my $p=pkg_dir($_); next unless outside($p);
  open my $fh,"<",$_ or next; local $/; my $c=<$fh>; close $fh;
  for my $e (keys %entity_patterns){
    for my $pat (@{$entity_patterns{$e}}){ if($c=~$pat){$refs{$e}{$p}=1; last} }
  }
}
for my $e (sort {scalar(keys %{$refs{$b}})<=>scalar(keys %{$refs{$a}})} keys %entity_patterns){
  print "$e: ", scalar(keys %{$refs{$e}}), " -> ", join(", ", sort keys %{$refs{$e}}), "\n";
}
'
